    base::as.character(code),
    "1" = "jlw_error",
    "2" = "jlw_argument",
    "3" = "jlw_dimension",
    "4" = "jlw_inexact",
    "5" = "jlw_bounds",
    "jlw_error"
  )
}

.jlr_abort <- function(code, msg) {
  base::stop(base::structure(
    class = base::c(.jlr_status_class(code), "jlw_error", "error", "condition"),
    base::list(message = msg, call = NULL, code = code)
  ))
